}

pub struct VideoMediaHydrator {
    pub tes_client: Arc<dyn TESClient + Send + Sync>,
    pub cache: QuickCache<u64, VideoMedia>,
}

impl VideoMediaHydrator {
    pub fn new(tes_client: Arc<dyn TESClient + Send + Sync>) -> Self {
